mapper.select:
SELECT event_id, answer_id, event_type, event_data, occurred_at
FROM qa_answer_event
WHERE answer_id = #{answerId}
  AND event_id > #{afterSequence}
ORDER BY event_id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM qa_answer_event
WHERE answer_id = #{answerId}
  AND event_id = #{sequence}

SELECT e.event_id, e.answer_id, e.event_type, e.event_data, e.occurred_at FROM qa_answer_event e INNER JOIN qa_answer a ON a.id = e.answer_id INNER JOIN qa_conversation c ON c.id = a.conversation_id WHERE c.id = #{conversationId} AND c.owner_id = #{ownerId} AND c.deleted_at IS NULL AND e.event_type NOT IN ('delta', 'metadata') AND e.answer_id IN
#{answerId}
ORDER BY e.event_id ASC
